from __future__ import absolute_import, division, print_function


class Infinity(object):
    """类 Infinity：封装与该模块相关的数据与行为。"""
    def __repr__(self):
        """函数 __repr__：核心业务逻辑。"""
        return "Infinity"

    def __hash__(self):
        """函数 __hash__：核心业务逻辑。"""
        return hash(repr(self))

    def __lt__(self, other):
        """函数 __lt__：处理 other 相关逻辑。"""
        return False

    def __le__(self, other):
        """函数 __le__：处理 other 相关逻辑。"""
        return False

    def __eq__(self, other):
        """函数 __eq__：处理 other 相关逻辑。"""
        return isinstance(other, self.__class__)

    def __ne__(self, other):
        """函数 __ne__：处理 other 相关逻辑。"""
        return not isinstance(other, self.__class__)

    def __gt__(self, other):
        """函数 __gt__：处理 other 相关逻辑。"""
        return True

    def __ge__(self, other):
        """函数 __ge__：处理 other 相关逻辑。"""
        return True

    def __neg__(self):
        """函数 __neg__：核心业务逻辑。"""
        return NegativeInfinity


Infinity = Infinity()


class NegativeInfinity(object):
    """类 NegativeInfinity：封装与该模块相关的数据与行为。"""
    def __repr__(self):
        """函数 __repr__：核心业务逻辑。"""
        return "-Infinity"

    def __hash__(self):
        """函数 __hash__：核心业务逻辑。"""
        return hash(repr(self))

    def __lt__(self, other):
        """函数 __lt__：处理 other 相关逻辑。"""
        return True

    def __le__(self, other):
        """函数 __le__：处理 other 相关逻辑。"""
        return True

    def __eq__(self, other):
        """函数 __eq__：处理 other 相关逻辑。"""
        return isinstance(other, self.__class__)

    def __ne__(self, other):
        """函数 __ne__：处理 other 相关逻辑。"""
        return not isinstance(other, self.__class__)

    def __gt__(self, other):
        """函数 __gt__：处理 other 相关逻辑。"""
        return False

    def __ge__(self, other):
        """函数 __ge__：处理 other 相关逻辑。"""
        return False

    def __neg__(self):
        """函数 __neg__：核心业务逻辑。"""
        return Infinity


NegativeInfinity = NegativeInfinity()
